// Prepara el aviso que manda el chatbot cuando una conversación necesita a una persona.
// Lo que llega viene de un visitante: se limpia y se recorta antes de usarlo.
const raw = $input.first().json;
const b = raw.body ?? raw;

const clip = (value, max) => String(value ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f]+/g, ' ').trim().slice(0, max);

const question = clip(b.question || b.message, 1000);
if (!question) throw new Error('El aviso llegó sin la pregunta del visitante');

const email = clip(b.email, 254).toLowerCase();
const hasEmail = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{2,}$/.test(email);

const name = clip(b.name, 100);
const parts = name.split(/\s+/).filter(Boolean);
const last = parts.length > 1 ? parts[parts.length - 1] : parts[0] || 'Chatbot visitor';
const first = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';

const reason = clip(b.reason || b.escalationReason, 300);
const page = clip(b.page, 200);
const session = clip(b.sessionId, 100);
const now = new Date().toISOString();

// Sin un email válido no hay a quién responder: no se crea ningún contacto en
// Zoho (se evitan registros basura) y solo se avisa al equipo.
let record = null;
if (hasEmail) {
  record = {
    First_Name: first,
    Last_Name: last,
    Email: email,
    Description: `Chatbot question: ${question}\nReason for escalation: ${reason || 'not given'}\nPage: ${page || 'not given'}`.slice(0, 5000),
    YB_Event: 'chat_escalation',
    Landing_Page: page,
    Last_Submission_Id: session,
    Last_Submitted_At: now,
  };
  for (const key of Object.keys(record)) {
    if (record[key] === '' || record[key] === undefined) delete record[key];
  }
}

return [{ json: { hasEmail, record, chat: { email: hasEmail ? email : '', name, question, reason, page, session, at: now } } }];

// Zoho responde 200/202 aunque rechace el registro (por ejemplo un campo que no
// existe). Sin esta comprobación el flujo diría "guardado" sin haber guardado nada.
// Si falla, el flujo termina con error y la web le pide a la persona que reintente.
const response = $input.first().json;
const result = Array.isArray(response.data) ? response.data[0] : null;

if (!result || result.status !== 'success' || !result.details || !result.details.id) {
  const why = result ? [result.code, result.message].filter(Boolean).join(' · ') : 'respuesta vacía';
  throw new Error('Zoho no guardó el contacto: ' + why);
}

return [{ json: { id: result.details.id, action: result.action || '' } }];

// Arma el correo al equipo cuando el chatbot pasa una conversación a una persona.
// Se ejecuta DESPUÉS de responder al chatbot. No se escribe a la persona que chatea:
// ya está en la conversación y su email podría no ser suyo.
const cfg = (name, fallback) => {
  try {
    return $vars[name] || fallback;
  } catch (e) {
    return fallback;
  }
};
const TEAM = String(cfg('YB_TEAM_EMAIL', '')).trim();
const TEAM_EMAILS_PER_DAY = 100;

const NAVY = '#031f3c';
const SAND = '#b8a27a';
const IVORY = '#f6f3ec';

const prepared = $('Preparar aviso').first().json;
const chat = prepared.chat || {};

const esc = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const oneLine = (value) => String(value ?? '').replace(/[\r\n\u0000-\u001f]+/g, ' ').trim();

if (!TEAM) return [];

const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (!store.day || store.day.date !== today) store.day = { date: today, visitor: 0, team: 0 };
if (store.day.team >= TEAM_EMAILS_PER_DAY) return [];
store.day.team += 1;

const note = chat.email
  ? 'The visitor left an email: the contact was created or updated in Zoho CRM (tag YB_CHATBOT).'
  : 'The visitor did NOT leave an email, so no contact was created in Zoho CRM and there is nobody to reply to.';

const rows = [
  ['Name', chat.name],
  ['Email', chat.email],
  ['Question', chat.question],
  ['Reason', chat.reason],
  ['Page', chat.page],
  ['Session', chat.session],
  ['Time', chat.at],
].filter(([, value]) => value && String(value).trim() !== '');

const table = `<table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 16px 0">${rows
  .map(
    ([key, value]) =>
      `<tr><td style="padding:8px 12px 8px 0;border-bottom:1px solid #efeadf;width:110px;vertical-align:top;font-size:11px;letter-spacing:1.2px;text-transform:uppercase;color:#8a7448">${esc(key)}</td>` +
      `<td style="padding:8px 0;border-bottom:1px solid #efeadf;vertical-align:top;font-size:14px;line-height:1.6;color:#1f2d3d;white-space:pre-line">${esc(value)}</td></tr>`,
  )
  .join('')}</table>`;

const html = `<!doctype html><html><body style="margin:0;padding:0;background:${IVORY}">
<table width="100%" cellpadding="0" cellspacing="0" style="background:${IVORY};padding:32px 0"><tr><td align="center">
<table width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#ffffff;border:1px solid #e4dfd3">
<tr><td style="background:${NAVY};padding:28px 36px">
<p style="margin:0;font-family:Arial,sans-serif;font-size:11px;letter-spacing:4px;text-transform:uppercase;color:${SAND}">YB University</p>
<h1 style="margin:10px 0 0 0;font-family:Georgia,serif;font-weight:normal;font-size:26px;line-height:1.2;color:#ffffff">A chat needs a person</h1>
</td></tr>
<tr><td style="padding:32px 36px 28px 36px;font-family:Arial,sans-serif">${table}
<p style="margin:0;font-size:12px;line-height:1.6;color:#5b6772">${esc(note)}</p></td></tr>
<tr><td style="background:${SAND};height:4px;font-size:0;line-height:0">&nbsp;</td></tr>
</table></td></tr></table></body></html>`;

const who = oneLine(chat.name || chat.email || 'anonymous visitor').slice(0, 80);
return [{ json: { to: TEAM, subject: `[YB chatbot] ${who}`, html } }];
